import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.CyZTVJbV.js";const p=JSON.parse('{"title":"kiwa v1.14 released — Payment + Search + Telemetry + Go Iris/Chi (横軸拡張)","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.14/gh-discussions-announcement.md","filePath":"announcements/v1.14/gh-discussions-announcement.md"}'),r={name:"announcements/v1.14/gh-discussions-announcement.md"};function i(n,e,l,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="kiwa-v1-14-released-—-payment-search-telemetry-go-iris-chi-横軸拡張" tabindex="-1">kiwa v1.14 released — Payment + Search + Telemetry + Go Iris/Chi (横軸拡張) <a class="header-anchor" href="#kiwa-v1-14-released-—-payment-search-telemetry-go-iris-chi-横軸拡張" aria-label="Permalink to &quot;kiwa v1.14 released — Payment + Search + Telemetry + Go Iris/Chi (横軸拡張)&quot;">​</a></h1><p>v1.14 is out. After 3 縦軸 milestones (v1.11 release gate → v1.12 non-determinism → v1.13 time-axis), v1.14 pivots to <strong>横軸拡張</strong> — adding the 4 SaaS provider categories that were on the v1.11+ backlog and completing perf measurement across all 9 kiwa targets.</p><h2 id="what-shipped" tabindex="-1">What shipped <a class="header-anchor" href="#what-shipped" aria-label="Permalink to &quot;What shipped&quot;">​</a></h2><ul><li><strong><code>@kiwa-lab/payment</code> v0.1</strong> — Stripe + Paddle + Lemon Squeezy webhook mock. HMAC-SHA256 signature verify with timing-safe compare, 4 fixture builders (<code>checkoutCompleted</code> / <code>subscriptionCreated</code> / <code>paymentFailed</code> / <code>refunded</code>), handler dispatch for e2e webhook flows.</li><li><strong><code>@kiwa-lab/search</code> v0.1</strong> — Meilisearch + Algolia + Typesense in-memory search mock. Word-overlap ranking, filter / facet / sort / pagination, 1-edit-distance typo tolerance (default matches each provider&#39;s production default).</li><li><strong><code>@kiwa-lab/observability</code> v1.1</strong> — 3 new telemetry mocks (OpenTelemetry + Datadog + Sentry). Unified <code>TelemetryCollector</code> shape (spans / metrics / logs / exceptions / transactions) so assertions read the same regardless of provider chosen.</li><li><strong><code>kiwa-test-go</code> v0.5</strong> — Iris + Chi subpackage. Same <code>TestServer</code> contract as v1.5+ gin / echo / fiber. Kiwa now covers <strong>5 Go web frameworks</strong> in one polyglot skill.</li><li><strong>perf 実測完遂</strong> — v1.13-1 landed the perf-harness with 5 targets. v1.14-1 extends to <strong>9 targets</strong> (added realtime + 3 realtime dogfood apps). All targets emit p95 reports under <code>docs/quality-reports/perf/</code> and pass the release gate.</li></ul><h2 id="numbers" tabindex="-1">Numbers <a class="header-anchor" href="#numbers" aria-label="Permalink to &quot;Numbers&quot;">​</a></h2><ul><li><strong>6 sub-Issues resolved</strong> (#722 + #725-#729)</li><li><strong>6 PRs merged</strong> (#723 + #730-#733 + #729-parent close)</li><li><strong>4 new packages / expansions</strong> (payment / search / observability v1.1 / go v0.5)</li><li><strong>9 perf targets</strong> with real p95 measurements + release-gate PASS</li></ul><h2 id="v1-15-candidates" tabindex="-1">v1.15+ candidates <a class="header-anchor" href="#v1-15-candidates" aria-label="Permalink to &quot;v1.15+ candidates&quot;">​</a></h2><ul><li>Reth (Rust Ethereum execution client, dApp testing depth)</li><li>Dragonfly (Redis-compatible modern cache)</li><li>Storybook integration</li><li>AI-LLM depth (multimodal / MCP tool / agent orchestration)</li><li>Framework depth (SolidJS, Fresh, HonoJS)</li></ul><p>Feedback welcome on which of these should land next.</p>',9)])])}const g=t(r,[["render",i]]);export{p as __pageData,g as default};
